_cache = {}
deleted = 'deleted'


def ocr_unknown_name(db):
    """对待定扣名单独调用OCR"""
    names = set()
    for r in db.sx_fold.find({'text': '?', deleted: None}, sort=[('bid', 1)]):
        han, vol_pdf, pi, idx, bid, end = [r[f] for f in [
            'han', 'vol_pdf', 'pi', 'idx', 'bid', 'end']]
        img_file = get_name_img(han, vol_pdf, pi, idx)
        n = call_ocr(db, img_file, han, vol_pdf, f'{bid}_{int(end)}')
        if n:
            names.add(r['pdf_name'])
    print(','.join(sorted(list(names))))


def fix_fold_no_name(db):
    """113条有扣图、没有扣名，补充扣名"""
    changed, warns = 0, []
    for r in db.sx_fold.find(dict(text=None, fold_mean={'$ne': None}), sort=[('bid', 1)]):
        _fill_one_fold_no(db, r, warns)
    print('\n'.join(warns))


