def fill_fold_lack_char(db, only_han=0):
    """对扣号文本缺少个别数字的进行修正"""
    changed, coll, max_nums = 0, db.sx_fold, {}
    cond = {'han': only_han} if only_han else {}

    # 撤销原先的自动补正
    coll.update_many({'fix_reason': {'$regex': '号，原扣号'}, **cond},
                     {'$set': {'text_status': 0}, '$unset': {'fix_reason': 1}})

    # 自动补正扣号，保留原始文本
    for r in coll.find({'text_status': 0, 'text': {'$regex': r'\d$'}, deleted: None,
                        **cond}, sort=[('bid', 1)]):
        han, vol_pdf, pid, bid, pi, idx = [r[f] for f in [
            'han', 'vol_pdf', 'pid', 'bid', 'pi', 'idx']]
        org_text = r.get('org_text') or r['text']
        a, _ = parse_name(org_text, idx)
        vol_fold, no_s = a[0][1:3]  # 扣名册号、扣号
        order = _get_order(db, pid)
        no_ok = vol_fold == str(vol_pdf) and make_page_no(han, vol_pdf, pi, idx, order)
        if not no_s or not no_ok or str(no_ok) == no_s:
            continue
        ok_s, like = str(no_ok), ''

        kv = _find_max_no_per_pi(max_nums, coll, cond, han, vol_pdf)
        due = _no_too_big(max_nums, kv, pi, no_ok)
        if due:  # 最大扣号小于计算扣号，很可能有重复页面
            coll.update_one({'_id': r['_id']}, {'$set': dict(text=org_text)})
            print(f"{bid},{vol_pdf},{no_s},{ok_s},{org_text},{org_text},"
                  f"因{due}，将 {r['text']} 恢复为原文本")
            continue

        if no_s in ok_s:
            like = '原扣号部分文本对'
        elif no_ok > 99 and len(no_s) > 1 and no_s[0] == ok_s[0] and no_s[-1] == ok_s[-1]:
            if no_s[1] == ' ':
                like = '原扣号中间是空格'
            elif len(no_s) == 2:
                like = '原扣号是少中间数字'
        elif 9 < no_ok < 100 and len(no_s) == 3 and no_s[1] == ' ' and \
                no_s[0] == ok_s[0] and no_s[-1] == ok_s[-1]:
            like = '原扣号中间多了空格'
        if like:
            text = re.sub(r'册.+$', f'册 {no_ok}', org_text)
            u = coll.update_one({'_id': r['_id']}, {'$set': dict(
                text=text, org_text=org_text, text_status=2, fix_reason=f'自动分配扣号，{like}')})
            if u.modified_count:
                changed += 1
                print(f'{bid},{vol_pdf},{no_s},{ok_s},{org_text},{text}')


def fill_fold_no(db):
    """对整册补充扣号文本"""
    changed, coll = 0, db.sx_fold
    for r in coll.find({'pdf_name': {'$in': ['忘字第07册', '恃字第05册']}, 'text': None,
                        'name_mean': {'$ne': None}}, sort=[('bid', 1)]):
        han, vol_pdf, pid, bid, pi, idx = [r[f] for f in [
            'han', 'vol_pdf', 'pid', 'bid', 'pi', 'idx']]
        order = _get_order(db, pid)
        no = make_page_no(han, vol_pdf, pi, idx, order)
        text = '大藏经' + r['pdf_name'].replace('第0', '第') + f' {no}'
        u = coll.update_one({'_id': r['_id']}, {'$set': dict(
            text=text, text_status=2, fix_reason=f'自动分配扣号')})
        if u.modified_count:
            changed += 1
            print(f'{bid},{vol_pdf},{no},{text}')


def _find_max_no_per_pi(max_nums, coll, q, han, vol_pdf):
    kv = f'{han}_{vol_pdf}'
    if kv not in max_nums:
        for r in coll.find({'text_status': 0, 'text': {'$regex': r'\d$'},
                            'han': han, 'vol_pdf': vol_pdf,
                            'org_text': None, deleted: None, **q},
                           dict(text=1, pi=1, bid=1), sort=[('pi', 1)]):
            a, _ = parse_name(r['text'], 1)
            vol2, no_s = a[0][1:3]
            if vol2 == str(vol_pdf) and re_digit.match(no_s):
                mk = max_nums[kv] = max_nums.get(kv) or dict(no=0, pi=-1, pi_no=[])
                if mk['no'] < int(no_s):
                    mk['no'] = int(no_s)
                    if mk['pi'] < r['pi']:
                        mk['pi'] = r['pi']
                        mk['pi_no'].append([r['pi'], mk['no'], r['text']])
                    else:
                        mk['pi_no'][-1][1] = mk['no']
                        mk['pi_no'][-1][2] = r['text']
    return kv


def _no_too_big(max_nums, kv, pi, no):
    d = max_nums.get(kv)
    if d:
        for pi_, no_, txt in max_nums[kv]['pi_no']:
            if pi > pi_:
                break
            if pi == pi_:
                return no > no_ + 10 and f'扣号大于当页的{no_}'
            if no >= no_:
                return f'扣号大于第{pi_ + 1}页的{no_}'


def _fill_many_fold_no(db, ids):
    warns = []
    for r in db.sx_fold.find(dict(bid={'$in': ids, deleted: None}), sort=[('bid', 1)]):
        _fill_one_fold_no(db, r, warns)
    print('\n'.join(warns))


def _fill_one_fold_no(db, r, warns, fix_prefix='', exclude_ids=None):
    han, vol_pdf, pid, bid, pi, idx = [r[f] for f in ['han', 'vol_pdf', 'pid', 'bid', 'pi', 'idx']]
    org_text = r.get('text')

    refs = [_get_fold_has_name(db, han, pid, i, exclude_ids)
            for i in range(10) if i != idx]
    refs = [f for f in refs if f and f.get('no')]  # (r, no, idx, no_ok)
    ref = refs and refs[0]
    bad = [f for f in refs if f['no'] != f['no_ok']]
    ref_text = refs and ref['r']['text'].strip()
    if not refs or bad:
        b = bad and bad[0]
        s = f"{len(bad)},{b['bid']} ({b['text']}) 扣号应为 {b['no_ok']}" if bad else ',没有参考扣'
        warns.append(f"{bid},{pid},{r.get('src', 'no-src')},{s}")
        return
    no = make_page_no(han, vol_pdf, pi, idx, ref['order'])
    text = re.sub(r'\d+$', str(no), ref_text)
    a, t = parse_name(text)
    assert t and int(a[0][2]) == no

    new_info = dict(text=text, org_text=org_text, text_status=2,
                    fix_reason=fix_prefix + f"参考{ref['r']['bid']}补全扣号")
    if not org_text:
        new_info.pop('org_text')
    if text == org_text:
        return

    u = db.sx_fold.update_one({'_id': r['_id'], deleted: None}, {'$set': new_info})
    if u.modified_count:
        print(f'{bid},{pid},{no},{text}')
    return u.modified_count


def _get_order(db, pid):
    ord_k = f'{pid}order'
    if not _cache.get(ord_k):
        p = db.sx_pdf_page.find_one({'pid': pid}, {'order': 1})
        _cache[ord_k] = p['order']
    return _cache[ord_k]


def _get_fold_has_name(db, han, pid, i, exclude_ids=None):
    """得到有扣号的扣记录"""
    r = db.sx_fold.find_one(dict(pid=pid, idx=i, deleted=None, text={'$nin': [None, '', '?']}))
    if r is not None and (not exclude_ids or r['bid'] not in exclude_ids):
        a, _ = parse_name(r['text'])
        if not re_digit.match(a[0][2] or ''):
            return dict(bid=r['bid'], text=r['text'], error='扣号错')
        no, idx = int(a[0][2]), i
        order = _get_order(db, pid)
        no_ok = make_page_no(han, vol_pdf, r['pi'], idx, order)
        return no and dict(r=r, no=no, idx=idx, no_ok=no_ok,
                           bid=r['bid'], text=r['text'], order=order)


def fix_ocr_text_149(db):
    """对扣号为149的重影扣名修正扣名"""
    ids = ['176_6_14_8', '177_1_14_8', '412_5_14_8', '419_5_14_8']
    changed = 0
    for r in db.sx_ocr.find({'bid': {'$in': ids}}):
        han, vol_pdf, pi, idx, text = [r[f] for f in ['han', 'vol_pdf', 'pi', 'idx', 'text']]
        next_r = db.sx_ocr.find_one(dict(han=han, vol_pdf=vol_pdf, pi=pi, idx=idx + 1))
        m = next_r and re.search(r'(^.+第\d+册\s*)(\d+)$', next_r['text'])
        if m and not re.search(r'册\s*\d+', text):
            new_text = m.group(1) + str(int(m.group(2)) - 1)
            u = db.sx_ocr.update_one({'_id': r['_id']}, {'$set': dict(
                text=new_text, org_text=text, fix_reason='扣号149重影')})
            changed += u.modified_count
    print(f'{changed} changed')


