def _fix_ocr_text_with(db, tsv_text, fix_reason):
    tsv = [s.strip().split('\t') for s in tsv_text.strip().split('\n')]
    d = {s[0]: s for s in tsv}
    changed, ok = 0, 0
    for r in db.sx_ocr.find({'bid': {'$in': list(d.keys())}}):
        bid, text, org_text = [r[f] for f in ['bid', 'text', 'org_text']]
        if d[bid][1] == org_text:
            ok += 1
            db.sx_ocr.update_one({'_id': r['_id']}, {'$set': dict(fix_reason=fix_reason)})
        elif d[bid][1] == text:
            u = db.sx_ocr.update_one({'_id': r['_id']}, {'$set': dict(
                text=d[bid][2], org_text=text, fix_reason=fix_reason)})
            changed += u.modified_count
    print(f'{changed} changed, {ok} exists')


def _fix_pdf_text_as_first_name(db, ids, fix_reason=''):
    changed = []
    for r in db.sx_pdf_page.find({'pid': {'$in': ids}}):
        pid, text, org_text = [r[f] for f in ['pid', 'text', 'org_text']]
        texts, old_text = text.split('\n'), text
        for i, t in enumerate(texts):
            texts[i] = re.sub(r'(册\s*\d+)(\s*大藏经.+$)', lambda m: m.group(1), t)
        text = '\n'.join(texts)
        if text != old_text and fix_reason:
            org_text = org_text or old_text
            u = db.sx_pdf_page.update_one({'_id': r['_id']}, {'$set': dict(
                fix_reason=fix_reason, text=text, org_text=org_text)})
            if u.modified_count:
                changed.append(pid)
    print(f"{len(changed)} changed: {','.join(changed)}")


def _update_words(db, ids, coll='sx_pdf_page'):
    re_w = re.compile(r'([\u4e00-\u9fa5],\d+,)(\d+[ \d]*)(,\d,[^,册]+册 )(\d+) ?(\n|$)')
    for r in db[coll].find({'pid': {'$in': ids}}):
        words, changed = r['words'].split('\n'), 0
        for i, w in enumerate(words):
            m = re_w.search(w)
            if m:
                a, b, c, d, e = [m.group(i + 1) for i in range(5)]
                s = ''.join([a, d, c, d, e])
                if s != w:
                    words[i] = s
                    changed += 1
        if changed:
            db[coll].update_one({'_id': r['_id']}, {'$set': {'words': '\n'.join(words)}})
            print(r['pid'])


def check_fold_names(db, only_han=0):
    """标记扣名册号、扣号、是否缺册号、缺扣号、多扣"""
    def add_check(**d):
        if d:
            if d['fold_no'] and not d.get('fold_id'):
                vol_ok = d.get('vol_ok') or d['vol_fold']
                d['fold_id'] = f"{d['han']}_{vol_ok}_{d['fold_no']}"
            buf.append((bid, d))
        if buf and (not d or len(buf) > 20):
            db.sx_fold_check.bulk_write([UpdateOne({'bid': b}, {'$set': d}, upsert=True)
                                         for b, d in buf])
            buf.clear()

    buf = []
    cond = dict(han=only_han, text={'$ne': None}, deleted=None)
    if not only_han:
        cond.pop('han')

    for r in db.sx_fold.find(cond, sort=[('bid', 1)]):
        han, vol_pdf, pid, bid, pi, idx, end = [r[f] for f in [
            'han', 'vol_pdf', 'pid', 'bid', 'pi', 'idx', 'end']]
        err_vol, err_no, fail_parse, ok = None, None, None, False
        vol_fold, fold_no, should_no = 0, 0, 0

        text = clean_text(r['text'])
        try:
            fail_parse = _check_text_can_not_parse(fail_parse, text)
            ps = parse_name(text, idx)
            kc, vol_fold_s, fold_no_s = list(ps[0][0])[:3]

            err_no, err_vol, fold_no, vol_fold = _check_vol_fold_no(
                err_no, err_vol, fold_no, vol_fold, fold_no_s, vol_fold_s)
            vol_fold = r.get('vol_fold') or vol_fold
            fold_no = r.get('fold_no') or fold_no

            ok = not (err_vol or err_no or fail_parse)
            if ok:
                should_no = _check_vol_after_ok(db, han, vol_fold, fold_no, should_no,
                                                vol_pdf, pid, pi, idx)
        except (IndexError, ValueError) as e:
            if not fail_parse and e:
                fail_parse = '其它错误'
        add_check(han=han, vol_pdf=vol_pdf, pid=pid, pi=pi, idx=idx, end=end, ok=ok,
                  should_no=should_no, vol_ok=r.get('vol_ok'),
                  fail_parse=fail_parse, err_vol=err_vol, err_fold_no=err_no,
                  vol_fold=vol_fold, fold_no=fold_no, pdf_name=r['pdf_name'],
                  empty=not r.get('fold_mean'), order=_get_order(db, pid),
                  text=None if ok and not should_no else text)
    add_check()


def _check_vol_after_ok(db, han, vol_fold, fold_no, should_no, vol_pdf, pid, pi, idx):
    if vol_fold != vol_pdf:
        should_no = 'vol_diff'
    else:
        right_no = make_page_no(han, vol_pdf, pi, idx, _get_order(db, pid))
        if right_no != fold_no:
            should_no = right_no
    return should_no


def _check_text_can_not_parse(fail_parse, text):
    if re.match(r'^\d+$', text):
        fail_parse = '扣名全是数字'
    elif '册' not in text:
        fail_parse = '没有册字'
    elif len(re.findall('册', text)) != 1:
        fail_parse = '多个册字'
    return fail_parse


def _check_vol_fold_no(err_no, err_vol, fold_no, vol_fold, fold_no_s, vol_fold_s):
    if not re.match(r'^\d+$', f'{vol_fold_s}'):
        err_vol = vol_fold_s or '?'
    else:
        vol_fold = int(vol_fold_s)
        if vol_fold < 1 or vol_fold > 548:
            err_vol = vol_fold or 'no'

    if not re.match(r'^\d+$', f'{fold_no_s}'):
        err_no = fold_no_s or '?'
    else:
        fold_no = int(fold_no_s)
        if fold_no < 1 or fold_no > 300:
            err_no = fold_no or 'no'
    return err_no, err_vol, fold_no, vol_fold


def check_fold_and_sum(db, only_han=0):
    def add_count(title, cond, level=1):
        n, rs, ps = coll.count_documents(cond), '', ''
        if n == 0:
            return
        if n < 100:
            r = coll.find_one(cond)
            text = r.get('text')
            no, vol_pdf = r.get('fold_no'), r.get('vol_fold')
            m1 = re.search(r'册\s(\d+)', text or '')
            same_no = '，号对' if m1 and int(m1.group(1)) == (r.get('should_no') or no) else ''
            r = f"\n\t{r['bid']}{f'(第{vol_pdf}册{no}扣{same_no})' if no else ''}" \
                f"{' “%s”' % text[:20] if text else ''}"
            rs += r

        if n < 10000:
            ps = list(coll.aggregate([{'$match': cond}, {'$group': {
                '_id': '$pid', 'n': {'$sum': 1}}}, {'$sort': {'n': -1, '_id': 1}}]))
            rs = f'、{len(ps)} 页' + rs
            ps = f"，例如 {'、'.join('%s(%d扣)' % (p['_id'], p['n']) for p in ps[:2])}"
        result.append('-' * level + f' {title}：{n} 条{rs}{ps}')

    # _fix_pdf_text_as_first_name(db, '406_5_7,409_1_9,409_3_8,517_2_2,97_9_9,405_6_6,'
    #                                 '518_6_4,380_5_6,412_1_12,441_1_8,422_1_12'.split(','))
    check_fold_names(db, only_han)
    coll, result = db.sx_fold_check, []

    add_count('有册号和扣号，扣号与连续规则一致', {'ok': True, 'should_no': 0})
    add_count('有册号和扣号，(扣名)册号与文件册号不同', {'should_no': 'vol_diff'})
    add_count('有册号和扣号，扣号与规则不一致', {'should_no': {'$gt': 0}})
    add_count('没有册号', {'err_vol': {'$ne': None}})
    add_count('没有扣号', {'err_fold_no': 'no'})

    add_count('无法解析册号（如下查询{fail_parse:type}）', {'fail_parse': {'$ne': None}})
    for m in ['扣名全是数字', '没有册字', '多个册字', '其它错误']:
        add_count(m, {'fail_parse': m}, 2)

    print('\n'.join(result))


def main(db_name='sx_pdf', func='', only_han=0):
    with_db(db_name, lambda db: eval(func or 'check_fold_and_sum')(db, int(only_han)))


if __name__ == '__main__':
    import fire

    fire.Fire(main)
